import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"兑为泽","description":"周易折中 - 兑为泽","frontmatter":{"title":"兑为泽","description":"周易折中 - 兑为泽"},"headers":[],"relativePath":"zh/classics/zhezhong/064.md","filePath":"zh/classics/zhezhong/064.md"}'),h={name:"zh/classics/zhezhong/064.md"};function n(p,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="兑为泽" tabindex="-1">兑为泽 <a class="header-anchor" href="#兑为泽" aria-label="Permalink to “兑为泽”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈兑序卦〉：“《巽》者，入也。入而后说之，故受之以《兑》。《兑》者，说也。物相入则相说，相说则相入。《兑》所以次《巽》也。”</p><p>兑：亨，利贞</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>兑，说也。一阴进乎二阳之上，喜之见乎外也。其象为泽，取其说万物，又取坎水而塞其下流之象。卦体刚中而柔外，刚中故说而亨，柔外故利于贞。盖说有亨道，而其妄说不可以不戒，故其占如此。又柔外故为说亨，刚中故利于贞，亦一义也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>兑，说也。说致亨之道也。能说于物，物莫不说而与之，足以致亨。然为说之道，利于贞正。非道求说，则为邪谄而有悔咎，故戒利贞也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>焦氏竑曰 ：人有喜说，必见而在外。盖阳假阴之和柔以为用，喜说非由于阴也。故二阴一阳则阳为之主，二阳一阴则阴非为主，但为阳之用耳。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>地有积湿，春气至则润升于上；人身有血，阳气盛则腴敷于色。此兑为泽、为说之义。盖说虽缘阴，而所以用阴者阳也。人有柔和之质，而非以忠直之心行之，则失正而入于邪矣。故利贞。</p><p>象曰：丽泽兑，君子以朋友讲习</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>两泽相丽，互相滋益，朋友讲习，其象如此。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>丽泽，二泽相附丽也。两泽相丽，交相浸润，互有滋益之象，故君子观其象而以朋友讲习。朋友讲习，互相益也。先儒谓天下之可说莫若朋友讲习，朋友讲习固可说之大者，然当明相益之象。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰 ：学以聚之，问以辨之。兑两口对，故朋友讲习也。</p></li><li><p>孔氏颖达曰 ：同门曰朋，同志曰友。朋友聚居，讲习道义，相说之盛，莫过于此也。</p></li><li><p>程子曰 ：天下之说不可极，惟朋友讲习，虽过说无害。兑泽有相滋益处。</p></li><li><p>苏氏轼曰 ：取其乐而不流者也。</p></li><li><p>朱氏震曰 ：讲其所知，习其所行。</p></li><li><p>蔡氏渊曰 ：讲兑象，习重兑象。</p></li><li><p>俞氏琰曰 ：讲者讲其所未明，讲多则义理明矣；习者习其所未熟，习久则践履熟矣。此朋友讲习所以为有滋益而如两泽之相丽也。若独学无友，则孤陋而寡闻。故《论语》以学之不讲为忧，以学而时习为说，以有朋自远方来为乐。</p></li></ul><p>彖曰：兑，说也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>释卦名义</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>张氏雨若曰：此释名义类《咸》，兑者无言之说，以说解兑，兑木为说，特以其说不在言而称兑耳。</li></ul><p>刚中而柔外，说以利贞，是以顺乎天而应乎人，说以先民，民忘其劳；说以犯难，民忘其死。说之大，民劝矣哉！</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦辞而极言之。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>兑之义说也。一阴居二阳之上，阴说于阳而为阳所说也。阳刚居中，中心诚实之象；柔爻在外，接物和柔之象，故为说而能贞也。利贞，说之道宜正也。卦有刚中之徳，能贞者也。说而能贞，是以上顺天理，下应人心，说道之至正至善者也。若夫违道以干百姓之誉者，苟说之道，违道不顺，天干誉非应人，苟取一时之说耳，非君子之正道。君子之道，其说于民，如天地之施，感于其心而说服无斁，故以之先民，则民心说随而忘其劳；率之以犯难，则民心说服于义而不恤其死。说道之大，民莫不知劝。劝，谓信之而勉力顺从。人君之道，以人心说服为本，故圣人赞其大。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：说而违刚则谄，刚而违说则暴。刚中而柔外，所以说以利贞也。刚中故利贞，柔外故说亨。</p></li><li><p>刘氏牧曰：天之所助者顺也，人之所助者信也。柔外为顺，刚中为信，故得顺乎天而应乎人。</p></li><li><p>吕氏祖谦曰：当适意时而说，与处安平时而说，皆未足为难。惟当劳苦患难而说，始见真说。圣人以此先之，故能使之任劳苦而不辞，赴患难而不畏也。</p></li></ul><p>初九：和兑，吉</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>以阳爻居说体而处最下，又无系应，故其象占如此。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>初虽阳爻居说体，而在最下，无所系应，是能卑下和顺以为说，而无所偏私者也。以和为说而无所偏私，说之正也。阳刚则不卑，居下则能巽，处说则能和，无应则不偏。处说如是，所以吉也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>蔡氏渊曰 ：爻位皆刚，不比于柔，得说之正，和而不流者也，故吉。</p></li><li><p>吴氏澄曰 ：六画唯初不比阴柔，说道之善，故曰“和”。</p></li><li><p>赵氏玉泉曰 ：阳刚则无邪媚之嫌，居下则无上求之念，无应又无私系之累。其说也不谄不凟，中节而无乖戾，和兑之象如是，则说得其正矣。</p></li><li><p>来氏知德曰 ：“和”，与《中庸》“发而皆中节谓之和”同。谓其所说者无乖戾之私，皆性情之正，道义之公也。</p></li></ul><p>象曰：和兑之吉，行未疑也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>居卦之初，其说也正，未有所疑也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>有求而和，则涉于邪谄。初随时顺处，心无所系，无所为也，以和而已，是以吉也。象又以其处说在下而非中正，故云行未疑也。其行末有可疑，谓未见其有失也。若得中正则无是言也，说以中正为本，爻直陈其义，象则推而尽之。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>蔡氏渊曰 ：初未牵于阴，所行未有疑惑。若四比三，有商兑之疑矣。</p></li><li><p>徐氏几曰 ：疑谓系于阴也。卦四阳，惟初与阴无系，故未疑。</p></li><li><p>郑氏维岳曰 ：以阳刚居兑初，又不与阴比，故信心信理而出行之于外者，未与心疑。使有系应，便不能自决矣。</p></li></ul><p>九二：孚兑，吉，悔亡</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>刚中为孚，居阴为悔。占者以孚而说，则吉而悔亡矣。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>二承比阴柔，阴柔小人也。说之则当有悔。二刚中之德，孚信内充，虽比小人，自守不失，君子和而不同，说而不失刚中，故吉而悔亡。非二之刚中，则有悔矣，以自守而亡也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏宗传曰 ：六三阴柔而不正，所谓非道以说者也。而二比之，疑于有悔矣。然二以刚居中，诚实之德充足于内，故虽与三同体而无失己之嫌，此其悔所以亡也。</p></li><li><p>龚氏焕曰 ：九二阳刚得中，当说之时，以孚信为说者也。已以孚信为说，人不得而妄说之，所以吉也。</p></li></ul><p>象曰：孚兑之吉，信志也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>心之所存为志，二刚实居中，孚信存于中也。志存诚信，岂至说小人而自失乎？是以吉也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>何氏楷曰 ：初去三远，不特志可信，而行亦未涉于可疑。二去三近，行虽不免于可疑，而志则可信。</li></ul><p>六三：来兑，凶</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>阴柔不中正，为兑之主，上无所应而反来就二阳以求说，凶之道也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>六三阴柔不中正之人，说不以道者也。来兑，就之以求说也。比于在下之阳，枉己非道就以求说，所以凶也。之内为来，上下俱阳而独之内者，以同体而阴性下也，失道下行也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏宗传曰 ：六三居两兑之闲，一兑既尽，一兑复来，故曰“来兑”。夫以不正之才，居两兑之闲，左右逢迎，惟以容说为事，此小人之失正者，故于兑为凶。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>三居内体，故曰“来”。然非来说于下二阳之谓也，为说之主，志在于说，凡外物之可说者皆感之而来也。</p><p>象曰：来兑之凶，位不当也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>自处不中正，无与而妄求说，所以凶也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>熊氏良辅曰 ：六三位不当，居上下二兑之闲。下兑方终，上兑又来，说而又说，不得其正者也。上六曰“引兑”，盖与六三相表里。</li></ul><p>九四：商兑，未宁，介疾有喜</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>四上承九五之中正，而下比六三之柔邪，故不能决而商度所说，未能有定然。质本阳刚，故能介然守正而疾恶柔邪，也如此则有喜矣。象占如此，为戒深矣。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>四上承中正之五，而下比柔邪之三。虽刚阳而处非正，三阴柔，阳所说也，故不能决而商度未宁，谓拟议所从而未决，未能有定也。两间谓之介，分限也（地之界则加田，义乃同也），故人有节守谓之介。若介然守正而疾远邪恶，则有喜也。从五正也，说三邪也。四近君之位，若刚介守正，疾远邪恶，将得君以行道，福庆及物，为有喜也。若四者得失未有定，系所从耳。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏简曰 ：九刚四柔，近比六三谀佞之小人，心知其非而实乐其柔媚，故商度所说去耶交战于胸中而未宁。圣人于是勉之曰：介然疾恶小人，则有喜。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>易中“疾”字皆与“喜”对，故曰“无妄之疾，勿药有喜”，又曰“损其疾，使遄有喜”。以此爻例之，则“疾”者谓疾病也，“喜”者谓病去也。四比于三，故曰“介疾”，言介于邪害之闲也。若安而溺焉，则其为鸩毒大矣。惟能商度所说而不以可说者为安，则虽介疾而有喜矣。《论语》曰：“君子易事而难说也，说之不以道，不说也。”其“商兑”之谓乎。</p><p>象曰：九四之喜，有庆也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>所谓喜者，若守正而君说之，则得行其阳刚之道，而福庆及物也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰 ：当兑之时，虞上下之际，不妄从说，知所择者也。介然自守，故能全兑说之喜。喜非独一身而已，终亦有及物之庆也。</li></ul><p>九五：孚于剥，有厉</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>剥谓阴能剥阳者也。九五阳刚中正，然当说之时而居尊位，宻近上六。上六阴柔，为说之主，处说之极，能妄说以剥阳者也。故其占但戒以信于上六，则有危也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>九五得尊位而处中正，尽说道之善矣。而圣人复设有厉之戒，盖尧舜之盛，未尝无戒也，戒所当戒而已。虽圣贤在上，天下未尝无小人，然不敢肆其恶也。圣人亦说其能勉而革面也。彼小人者，未尝不知圣贤之可说也，如四凶处尧朝，隐恶而顺命是也。圣人非不知其终恶也，取其畏罪而强仁耳。五若诚心信小人之假善为实善，而不知其色藏，则危道也。小人者，备之不至则害于善。圣人为戒之意深矣。剥者，消阳之名，阴消阳者也，盖指上六。故孚于剥则危也。以五在说之时而宻比于上六，故为之戒。虽舜之圣，且畏巧言令色，安得不戒也？说之惑人易入而可惧也如此。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：比于上六而与相得，处尊正之位，不说信乎阳而说信乎阴，孚于剥之义也。剥之为义，小人道长之谓。</p></li><li><p>杨氏简曰 ：九五亲信上六柔媚不正之小人，故曰“孚于剥”。剥之为卦，小人剥君子，又剥丧其国家，故谓小人为剥。信小人，危厉之道也。</p></li><li><p>胡氏炳文曰 ：说之感人最为可惧，感之者将以剥之也。况为君者易狃于所说，故虽圣人且畏巧言令色，况凡为君子者乎？</p></li><li><p>钱氏一本曰 ：兑五说体与履五健体不同，履五健，恐其和之难，危在夬；兑五说，不觉其入之易，危在孚。故皆有厉之象。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>易中凡言“厉”者，皆兼内外而言，盖事可危而吾危之也。履五爻及此爻，皆以刚中正居尊位而有厉辞。夫子又皆以位正当释之，是其危也。以刚中正，故能危也。履卦有危惧之义，而九五居尊，所谓“履帝位而不疚”者，故能因夬履而常危；兑有说义，九五居尊，又比上六，故亦因孚于剥而心有危也。此有厉与夬有厉正同，皆以九五比近上六，所谓其危乃光者也。</p><p>象曰：孚于剥，位正当也</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>与履九五同。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>戒孚于剥者，以五所处之位正当戒也。密比阴柔，有相说之道，故戒在信之也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰 ：谓正当尊位，若孚上之柔说，则消剥于阳必矣。</li></ul><p>上六：引兑</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>上六成说之主，以阴居说之极，引下二阳相与为说，而不能必其从也。故九五当戒，而此爻不言其吉凶。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>他卦至极则变，兑为说极则愈说。上六成说之主，居说之极，说不知已者也。故说既极矣，又引而长之。然而不至悔咎，何也？曰方言其说，不知已，未见其所说善恶也。又下乘九五之中正，无所施其邪说。六三则承乘皆非正，是以有凶。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>刘氏牧曰 ：执德不固，见诱则从，故称“引兑”。</p></li><li><p>毛氏璞曰 ：所以为兑者，三与上也。三为内卦，故曰“来”；上为外卦，故曰“引”。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>三与上皆以阴柔为说主。来兑者，物感我而来，孟子所谓“蔽于物”，乐记所谓“感于物而动”者也。引兑者，物引我而去，孟子所谓“物交物则引之而已矣”，乐记所谓“物至而人化物”者也。始于来，终于引，此人心动乎欲之浅深也。</p><p>象曰：上六引兑，未光也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>说既极矣，又引而长之，虽说之之心不已，而事理已过，实无所说。事之盛则有光辉，既极而强引之长，其无意味甚矣，岂有光也？“未”非必之辞，象中多用“非必”，能有光辉谓不能光也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏启新曰 ：来兑、引兑皆小人也。在君子，则当来而勿受，引而勿去也。君子以道德相引，其道为光明。引而为说，则心术暧昩，行事邪僻，甚矣，岂得为光乎？</li></ul><p>总论</p><ul><li><p>龚氏焕曰 ：兑本以说之见乎外而得名，然六爻之义皆不取说之徇乎外者。人之所说苟能不徇乎外，则其见于外者斯得其正而吉矣。</p></li><li><p>蒋氏悌生曰 ：当说之时，刚则有节，柔则无度。故此卦初二及四五四爻皆以刚阳而得吉，三上二爻皆以阴柔而致凶。</p></li></ul>',117)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
